<?php
session_start();if(!isset($_SESSION['user_id'])||$_SESSION['role']!=='patient'){header('Location: ../auth/login.php');exit();}include('../config/database.php');$user_id=(int)$_SESSION['user_id'];$name=$_SESSION['name'];$pq=mysqli_query($conn,"SELECT id FROM patients WHERE user_id=$user_id LIMIT 1");$p=mysqli_fetch_assoc($pq);$patient_id=(int)$p['id'];$today=date('Y-m-d');$q=mysqli_query($conn,"SELECT a.id,a.token_number,a.doctor_id,a.appointment_time,u.name doctor_name,d.name department_name,dr.avg_consultation_minutes FROM appointments a JOIN doctors dr ON a.doctor_id=dr.id JOIN users u ON dr.user_id=u.id JOIN departments d ON dr.department_id=d.id WHERE a.patient_id=$patient_id AND a.appointment_date='$today' AND a.status IN('pending','confirmed') ORDER BY a.token_number ASC LIMIT 1");$mine=mysqli_fetch_assoc($q);$serving=null;$ahead=0;$wait=0;if($mine){$s=mysqli_query($conn,"SELECT token_number FROM appointments WHERE doctor_id=".(int)$mine['doctor_id']." AND appointment_date='$today' AND queue_status='serving' LIMIT 1");$serving=mysqli_fetch_assoc($s);$current=$serving?(int)$serving['token_number']:0;$ahead=$serving?max(0,(int)$mine['token_number']-$current):max(0,(int)$mine['token_number']-1);$wait=$ahead*(int)$mine['avg_consultation_minutes'];} ?><!DOCTYPE html><html><head><meta http-equiv="refresh" content="10"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Queue | ClinicCare</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/patient.css"></head><body><div class="patient-layout"><aside class="patient-sidebar"><div class="patient-brand"><div class="patient-brand-icon"><i class="fa-solid fa-plus"></i></div><div><h3>ClinicCare</h3><span>Patient Portal</span></div></div><div class="patient-profile"><div class="patient-avatar-small"><?php echo strtoupper(substr($name,0,1));?></div><div class="patient-profile-info"><strong><?php echo htmlspecialchars($name);?></strong><span>Patient</span></div></div><nav class="patient-nav"><div class="patient-nav-heading">MAIN MENU</div><a href="dashboard.php" class="patient-nav-link"><i class="fa-solid fa-chart-line patient-nav-icon"></i>Dashboard</a><a href="book_appointment.php" class="patient-nav-link"><i class="fa-solid fa-calendar-plus patient-nav-icon"></i>Book Appointment</a><a href="appointments.php" class="patient-nav-link"><i class="fa-solid fa-calendar-check patient-nav-icon"></i>Appointments</a><a href="queue.php" class="patient-nav-link active"><i class="fa-solid fa-users patient-nav-icon"></i>Live Queue</a><a href="prescriptions.php" class="patient-nav-link"><i class="fa-solid fa-prescription-bottle-medical patient-nav-icon"></i>Prescriptions</a><a href="notifications.php" class="patient-nav-link"><i class="fa-solid fa-bell patient-nav-icon"></i>Notifications</a></nav><div class="patient-sidebar-bottom"><a href="../auth/logout.php" class="patient-logout"><i class="fa-solid fa-right-from-bracket"></i>Logout</a></div></aside><main class="patient-main"><header class="patient-topbar"><div><h1>Live Queue</h1><p>Your queue position refreshes automatically every 10 seconds.</p></div></header><div class="patient-content"><?php if($mine){?><section class="patient-card"><div class="patient-card-header"><div><h2>Dr. <?php echo htmlspecialchars($mine['doctor_name']);?></h2><p><?php echo htmlspecialchars($mine['department_name']);?></p></div><span class="cc-badge cc-badge-primary">Today</span></div><div class="patient-card-body"><div class="queue-large"><div style="font-size:10px;color:#7DD3FC;letter-spacing:1px">YOUR TOKEN</div><div class="token">#<?php echo $mine['token_number'];?></div><div style="font-size:12px;color:#CBD5E1">Appointment at <?php echo date('h:i A',strtotime($mine['appointment_time']));?></div><div style="margin-top:18px;font-size:11px;color:#CBD5E1"><?php echo $serving?'Now serving token #'.(int)$serving['token_number']:'Queue not started yet';?></div></div><div class="queue-meta"><div class="queue-meta-card"><span>Now Serving</span><strong><?php echo $serving?$serving['token_number']:'-';?></strong></div><div class="queue-meta-card"><span>Patients Ahead</span><strong><?php echo $ahead;?></strong></div><div class="queue-meta-card"><span>Estimated Wait</span><strong><?php echo $wait;?> min</strong></div></div><div style="text-align:center;margin-top:18px;font-size:13px;color:var(--cc-blue-dark)"><?php echo $serving&&((int)$serving['token_number']==(int)$mine['token_number'])?'It is your turn.':($ahead==1?'Your turn is next.':($serving?'Please stay nearby and monitor the queue.':'Queue has not started.'));?></div></div></section><?php }else{?><section class="patient-card"><div class="cc-empty"><div class="cc-empty-icon"><i class="fa-solid fa-users"></i></div><h3>No active appointment today</h3><p>Book or check your appointment list.</p><a href="appointments.php" class="patient-primary-btn">My Appointments</a></div></section><?php }?></div></main></div></body></html>
